export function showcasePixelRatio(preview = false) {
  const deviceRatio = Math.max(.5, Number(window.devicePixelRatio) || 1);
  if (!preview) return Math.min(deviceRatio, 2);
  let hostWidth = window.innerWidth;
  try { if (window.parent !== window) hostWidth = window.parent.innerWidth; } catch { /* Cross-origin embeds keep the local width. */ }
  const maximumPixels = hostWidth <= 760 ? 420000 : 900000;
  const logicalPixels = Math.max(1, window.innerWidth * window.innerHeight);
  return Math.min(1, deviceRatio, Math.max(.5, Math.sqrt(maximumPixels / logicalPixels)));
}

export function showcaseTextureLimit(preview = false) {
  if (!preview) return 1920;
  let hostWidth = window.innerWidth;
  try { if (window.parent !== window) hostWidth = window.parent.innerWidth; } catch { /* Cross-origin embeds keep the local width. */ }
  return hostWidth <= 760 ? 768 : 1280;
}
